import { useEffect, useState, useCallback } from "react";
import axios from "axios";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
} from "chart.js";
import { Bar } from "react-chartjs-2";

// Register chart components
ChartJS.register(
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend
);

const API_URL = "http://localhost:5000";
const REFRESH_INTERVAL = 2000;

function AdminAnonymousResults({ theme }) {
  const [candidates, setCandidates] = useState([]);
  const [loading, setLoading] = useState(true);

  // Fetch candidates (memoized for stability)
  const fetchCandidates = useCallback(async () => {
    try {
      const { data } = await axios.get(`${API_URL}/api/candidates`);
      setCandidates(data);
    } catch (error) {
      console.error("Error fetching candidates:", error);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchCandidates();

    const interval = setInterval(fetchCandidates, REFRESH_INTERVAL);
    return () => clearInterval(interval);
  }, [fetchCandidates]);

  // Group candidates by position
  const groupedCandidates = candidates.reduce((acc, candidate) => {
    const position = candidate.candidacy || "Other";
    if (!acc[position]) acc[position] = [];
    acc[position].push(candidate);
    return acc;
  }, {});

  if (loading) {
    return <div style={{ padding: 20 }}>Loading results...</div>;
  }

  return (
    <div style={{ padding: "20px 30px" }}>
      <h2 style={{ marginBottom: 30 }}>Anonymous Election Monitor</h2>

      {Object.entries(groupedCandidates).map(([position, list]) => {
        const sortedCandidates = [...list].sort(
          (a, b) => (b.votes || 0) - (a.votes || 0)
        );

        const chartData = {
          labels: sortedCandidates.map(
            (_, index) => `Candidate ${index + 1}`
          ),
          datasets: [
            {
              label: `${position} Votes`,
              data: sortedCandidates.map((c) => c.votes || 0),
              backgroundColor: theme.button || "#4CAF50",
              borderRadius: 6,
            },
          ],
        };

        const chartOptions = {
          responsive: true,
          plugins: {
            legend: {
              display: true,
              position: "top",
            },
            title: {
              display: false,
            },
          },
          scales: {
            y: {
              beginAtZero: true,
              ticks: {
                precision: 0,
              },
            },
          },
        };

        return (
          <div
            key={position}
            style={{
              marginBottom: 40,
              backgroundColor: theme.card || "#fff",
              padding: 20,
              borderRadius: 12,
              boxShadow: "0 4px 10px rgba(0,0,0,0.08)",
            }}
          >
            <h3 style={{ marginBottom: 15 }}>{position}</h3>
            <Bar data={chartData} options={chartOptions} />
          </div>
        );
      })}
    </div>
  );
}

export default AdminAnonymousResults;
